fn loop_calc(mut first_num: i32, mut second_num: i32, limit: u8) {
    for _i in 2..limit {
        let sum_num = first_num + second_num;
        first_num = second_num;
        second_num = sum_num;
        println!(&quot;next val is {}&quot;, sum_num);
    }
}

fn fib_loop(n: u8) {
    let a = 1;
    let b = 1;
    loop_calc(a, b, n);
}

fn fib_while(n: u8) {
    let (a, b) = (1, 1);
    loop_calc(a, b, n);
}

fn fib_for(n: u8) {
    let (a, b) = (1, 1);
    loop_calc(a, b, n);
}

